import { describe, expect, it } from 'vitest';
import { RateLimiter } from '../src/lib/limiter';
import { setup } from './helpers';

describe('POST /webhooks rate limiting', () => {
  it('answers 429 with a Retry-After header when a tenant exceeds the limit', async () => {
    const { postWebhook } = setup({ rateLimitMaxRequests: 2, rateLimitWindowMs: 60000 });
    expect((await postWebhook('tenant-a', { type: 'a' })).status).toBe(202);
    expect((await postWebhook('tenant-a', { type: 'b' })).status).toBe(202);

    const res = await postWebhook('tenant-a', { type: 'c' });
    expect(res.status).toBe(429);
    const retryAfter = res.headers.get('Retry-After');
    expect(retryAfter).not.toBeNull();
    expect(Number(retryAfter)).toBeGreaterThan(0);
    expect(await res.json()).toMatchObject({ error: 'rate limit exceeded' });
  });

  it('does not affect other tenants', async () => {
    const { postWebhook } = setup({ rateLimitMaxRequests: 1, rateLimitWindowMs: 60000 });
    expect((await postWebhook('tenant-a', { type: 'a' })).status).toBe(202);
    expect((await postWebhook('tenant-a', { type: 'b' })).status).toBe(429);
    expect((await postWebhook('tenant-b', { type: 'b' })).status).toBe(202);
  });

  it('does not store or audit a rejected webhook', async () => {
    const { postWebhook, deps } = setup({ rateLimitMaxRequests: 1, rateLimitWindowMs: 60000 });
    expect((await postWebhook('tenant-a', { type: 'a' })).status).toBe(202);
    expect((await postWebhook('tenant-a', { type: 'b' })).status).toBe(429);
    expect(deps.store.listByTenant('tenant-a')).toHaveLength(1);
    expect(deps.audit.list('tenant-a')).toHaveLength(1);
  });

  it('reads the limit from config rather than a constant', async () => {
    const { postWebhook } = setup({ rateLimitMaxRequests: 3, rateLimitWindowMs: 60000 });
    for (let i = 0; i < 3; i += 1) {
      expect((await postWebhook('tenant-a', { type: `t${i}` })).status).toBe(202);
    }
    expect((await postWebhook('tenant-a', { type: 'over' })).status).toBe(429);
  });
});

describe('RateLimiter', () => {
  it('allows requests again once the window passes', () => {
    const limiter = new RateLimiter();
    expect(limiter.check('t', 1, 1000, 0).allowed).toBe(true);
    const denied = limiter.check('t', 1, 1000, 500);
    expect(denied.allowed).toBe(false);
    expect(denied.retryAfterSec).toBeGreaterThan(0);
    expect(limiter.check('t', 1, 1000, 1001).allowed).toBe(true);
  });

  it('tracks tenants independently', () => {
    const limiter = new RateLimiter();
    expect(limiter.check('a', 1, 1000, 0).allowed).toBe(true);
    expect(limiter.check('a', 1, 1000, 0).allowed).toBe(false);
    expect(limiter.check('b', 1, 1000, 0).allowed).toBe(true);
  });
});

